for job in (root/'artifacts/harbor-runs').glob(campaign.name+'-*'):
 for f in job.glob('*/exception.txt'):
  result=f.parent/'result.json';d=json.loads(result.read_text()) if result.exists() else {};info=d.get('exception_info') or {};errors.append(dict(trial=str(f.parent.relative_to(root)),exception_type=info.get('exception_type') or info.get('type') or 'see_raw_native_log',raw_log=str(f.relative_to(root))))
failed=next((root/'artifacts/harbor-runs'/(campaign.name+'-daytona')).glob('task__aUYod56/agent/trajectory.json'));failed_cost=json.loads(failed.read_text()).get('info',{}).get('model_stats',{}).get('instance_cost')
report=dict(harness_commit=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),status='completed_validated',campaign=campaign.name,completed_at=datetime.datetime.now(datetime.timezone.utc).isoformat(),protocol='polytopia-skirmish-continuous-v1',coding_seconds=2400,attempts_per_model=5,models=12,authored_submissions=60,total_final_outcomes=21600,score_definition='100 * (wins + 0.5 * draws) / 360 per authored bot; mean and sample SD across five bots per model',schedule_sha256=next(iter(schedules)),selection_rule=registry['selection_rule'],validation_kinds=registry['validation_kinds'],leaderboard=leaderboard,trials=trials,infrastructure=dict(authoring_retry=json.loads((campaign/'infrastructure-retry.json').read_text()),grading_recoveries=json.loads((campaign/'grading-recovery-jobs.json').read_text()),raw_native_failures=errors),costs=dict(completed_call_openrouter_usd=sum(r['completed_call_cost_usd'] for r in leaderboard if r['completed_call_cost_usd'] is not None),failed_authoring_completed_call_usd=failed_cost,proxy_subscription_cost_usd=None,daytona_settled_cost_usd=None,note='Completed-response inference charges exclude potentially billed interrupted calls and setup probes. Proxy subscription cost and settled Daytona charges are not available from these receipts.'),limitations=['Local proxy trials used ARM Docker/Colima; OpenRouter trials used x86_64 Daytona, with the same declared runtime limits.','Scores include endpoint latency under concurrent load.','Standard deviation measures variation across five authored bots on this fixed panel.','Lossless replay exports preserve all original native audited action entries and hashes; their public observations are reconstructed with the pinned native engine. Raw public bytes were locally rehashed for full exports; decoder equivalence was qualified against 36 complete original games.'])
(output/'build-provenance.json').write_text(json.dumps({backend:json.loads((root/'artifacts/harbor-packages'/('split-'+backend+'-release-v6-20261031')/'build.json').read_text()) for backend in ('local','daytona')},indent=2)+'\n')
(output/'results.json').write_text(json.dumps(report,indent=2)+'\n');(output/'leaderboard.json').write_text(json.dumps(leaderboard,indent=2)+'\n')
lines=['# Polytopia Skirmish: complete continuous benchmark','',f'**12 models × five independently authored bots × 360 final games = 21,600 outcomes.** Each author had up to 40 active minutes, including public practice, compilation and trace inspection. All submissions were frozen before final judging.','', 'Primary score is 100 × (wins + half of draws) / 360. The table reports the mean and sample SD across five authored bots. Every bot faced the same six-opponent, three-family, ten-layout, both-seat schedule.','', '| Model | Panel points /100, mean ± SD | Champion wins | Recorded API USD |','|---|---:|---:|---:|']
for r in leaderboard:
 cost=f"${r['completed_call_cost_usd']:.2f}" if r['completed_call_cost_usd'] is not None else 'Subscription / unavailable'
